"""Offline viewer of the saved source and bridge arrays, no simulated model output."""
import argparse,base64,json
from pathlib import Path
import numpy as np
from dunhuang.research.complete_r36.core import read,write,sha

def run(main,out):
    out=Path(out)
    if out.exists():raise ValueError('Fresh viewing package')
    out.mkdir(parents=True);main=Path(main);meta=read(main/'result.json');z=np.load(main/'arrays.npz');records=[]
    for r in meta['records']:
        key=r['key'];payload={}
        for name in ['source']+r['methods']:
            v=z[key+'_source'] if name=='source' else z[key+'_'+name+'_P'];payload[name]=base64.b64encode(v.astype('<f4').tobytes()).decode()
        records.append(dict(key=key,kind=r['kind'],left=r['left']['source_uid'],right=r['right']['source_uid'],left_unit=r['left']['unit_uid'],right_unit=r['right']['unit_uid'],source_window=r['source_window'],payload=payload,source_valid=z[key+'_source_valid'].tolist(),metrics=r['metrics'],screens=r['screens'],certificates=r['certificates'],selected=r['selected'],rejection=r['rejection']))
    data=dict(records=records,parents=z['parents'].tolist(),reference=meta['reference'],controls=meta['controls']);(out/'data.js').write_text('window.R48='+json.dumps(data,ensure_ascii=False,allow_nan=False)+';',encoding='utf8')
    (out/'index.html').write_text('''<!doctype html><html lang="zh"><meta charset="utf-8"><title>R48 实际来源与动态桥</title><link rel="stylesheet" href="style.css"><header><small>DUNHUANG · R48 RESEARCH</small><h1>新事件之间，怎样连接更合适？</h1><p>实际保存的 Source／G0／G1／G3；G2仅在后续对照页出现。本轮没有神经训练或扩散生成。</p><p>共同30Hz时钟、固定相机与比例。新接法没有真实配对音乐，不伪造配乐；22关节局部姿态无法证明世界Root、接触或完整手势。</p></header><main><label>案例 <select id="case" aria-label="案例"></select></label><button id="play">播放 / 暂停</button><button id="prev">前一帧</button><button id="next">后一帧</button><button id="jump">第117帧</button><label>倍速 <select id="rate" aria-label="倍速"><option value="1">1×</option><option value="0.5">0.5×</option><option value="0.25">0.25×</option></select></label><p id="clock"></p><input id="seek" aria-label="动作帧" type="range" min="0" max="255" value="0"><p id="scope"></p><div id="methods"></div><section id="panels"></section><canvas id="curve" width="1100" height="130" aria-label="实际Jerk曲线"></canvas><p>橙色 [104,152) 是桥接区。点击曲线或拖动滑条可以定位异常；Source缺口只在同一连续录制有真实答案，异源案例明确留空。</p><details><summary>来源身份、准入与指标</summary><pre id="details"></pre></details><p>绝对动力学阈值来自固定Train来源Q95，构形来自Train肩腕范围，均为数值参考，不是Native或自然性资格。未过关接法保留拒绝状态，不输出伪合格整曲。</p></main><script src="data.js"></script><script src="viewer.js"></script></html>''',encoding='utf8')
    (out/'style.css').write_text('body{margin:24px auto;max-width:1400px;background:#f5f3ec;color:#203a39;font:17px system-ui}header,main{padding:22px}header{border-bottom:2px solid #b2c6be}button,select{padding:9px;margin:5px;border:1px solid #9eafa6;border-radius:6px;background:white;color:#203a39}input[type=range]{width:100%}#panels{display:flex;flex-wrap:wrap;gap:12px}article{flex:1;min-width:280px;background:white;border:1px solid #d3dace;padding:12px;border-radius:10px}canvas{max-width:100%}h3{margin:8px 0}pre{white-space:pre-wrap;font-size:13px}#scope{background:#e5eadd;padding:12px}#methods label{margin-right:18px}',encoding='utf8')
    (out/'viewer.js').write_text(JS,encoding='utf8');write(out/'protocol.json',dict(cases=len(records),source_arrays_sha256=sha(main/'arrays.npz'),files=[dict(name=p.name,bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(out.iterdir())],common_clock_fps=30,neural_samples=0,paired_music=False))

JS=r'''const $=id=>document.getElementById(id),D=window.R48;let row,frame=0,playing=false,last=0,tracks={},enabled=new Set(['source','G0','G3']);
function decode(s){let b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return new Float32Array(u.buffer)}
D.records.forEach((r,i)=>{$('case').add(new Option(r.key,i))});
function load(){playing=false;row=D.records[+$('case').value];tracks={};Object.entries(row.payload).forEach(([k,v])=>tracks[k]=decode(v));$('methods').innerHTML='';Object.keys(tracks).forEach(k=>{let l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.checked=enabled.has(k);c.onchange=()=>{c.checked?enabled.add(k):enabled.delete(k);panels()};l.append(c,document.createTextNode(k));$('methods').append(l)});$('scope').textContent=row.kind+' · '+row.left+' → '+row.right+' · '+(row.selected?'数值研究候选 '+row.selected+'，尚无物理资格':'拒绝当前接法：无方法通过登记筛查');$('details').textContent=JSON.stringify({...row,payload:undefined,source_valid:undefined},null,2);panels();seek(0)}
function panels(){$('panels').innerHTML='';Object.keys(tracks).filter(k=>enabled.has(k)).forEach(k=>{let a=document.createElement('article'),h=document.createElement('h3'),c=document.createElement('canvas');h.textContent=k;c.width=400;c.height=450;c.dataset.method=k;a.append(h,c);$('panels').append(a)});draw()}
function point(p,j){let i=(frame*22+j)*3;return[200+(p[i]*.86-p[i+2]*.5)*150,250-p[i+1]*150]}
function draw(){document.querySelectorAll('article canvas').forEach(c=>{let ctx=c.getContext('2d'),k=c.dataset.method;ctx.clearRect(0,0,400,450);ctx.fillStyle='#203a39';ctx.font='16px sans-serif';if(k==='source'&&!row.source_valid[frame]){ctx.fillText('异源连接：无唯一隐藏来源真值',35,210);return}let p=tracks[k];for(let j=1;j<22;j++){let a=point(p,D.parents[j]),b=point(p,j);ctx.strokeStyle=j%2?'#1b7b6e':'#bd8143';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}ctx.fillText('局部姿态 · 世界Root/接触 UNKNOWN',20,420)});$('clock').textContent=(frame/30).toFixed(6)+' 秒 · 帧 '+frame+'/255 · '+(frame>=104&&frame<152?'桥接区':'受保护来源');$('seek').value=frame;let c=$('curve'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#f0d8aa';ctx.fillRect(104/255*c.width,0,48/255*c.width,c.height);let max=Math.max(1,...Object.values(row.metrics).flatMap(m=>m.jerk_curve));Object.entries(row.metrics).filter(([k])=>enabled.has(k)).forEach(([k,m],i)=>{ctx.strokeStyle=['#b35f45','#36756a','#6781ba','#76616c'][i%4];ctx.beginPath();m.jerk_curve.forEach((v,t)=>{let x=t/255*c.width,y=120-v/max*110;t?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.fillText(k,20+i*80,15)});ctx.strokeStyle='#122';ctx.beginPath();ctx.moveTo(frame/255*c.width,0);ctx.lineTo(frame/255*c.width,130);ctx.stroke()}
function seek(t){frame=Math.max(0,Math.min(255,Math.round(t)));draw()}
$('case').onchange=load;$('prev').onclick=()=>{playing=false;seek(frame-1)};$('next').onclick=()=>{playing=false;seek(frame+1)};$('jump').onclick=()=>{playing=false;seek(117)};$('seek').oninput=()=>{playing=false;seek(+$('seek').value)};$('play').onclick=()=>{playing=!playing;last=performance.now()};$('rate').onchange=()=>last=performance.now();$('curve').onclick=e=>{playing=false;let r=e.target.getBoundingClientRect();seek((e.clientX-r.left)/r.width*255)};function tick(t){if(playing){let n=Math.floor((t-last)/1000*30*+$('rate').value);if(n>0){last+=n/(30*+$('rate').value)*1000;seek(frame+n);if(frame===255)playing=false}}requestAnimationFrame(tick)}load();requestAnimationFrame(tick);'''

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--main',required=True);p.add_argument('--out',required=True);a=p.parse_args();run(a.main,a.out)
